import{_ as t,o as a,c as i,ag as n}from"./chunks/framework.CxkNbRKf.js";const o="/nada-documentation/images/image77.png",r="/nada-documentation/images/image78.png",s="/nada-documentation/images/image79.png",c="/nada-documentation/images/image80.png",_=JSON.parse('{"title":"Regions","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/regions.md","filePath":"admin-guide/web-ui/regions.md","lastUpdated":1786379412000}'),g={name:"admin-guide/web-ui/regions.md"};function d(p,e,u,h,m,l){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="regions" tabindex="-1">Regions <a class="header-anchor" href="#regions" aria-label="Permalink to &quot;Regions&quot;">​</a></h1><p><img src="'+o+'" alt=""></p><p>By region, we mean &quot;country groups&quot;. The regions can be of different types, determined based on a geographic criterion (e.g., by continent), an administrative criteria (e.g., &quot;OECD countries&quot;), an economic criteria (e.g., high/middle/low-income countries), or other type of criteria (e.g., &quot;landlocked&quot;). In the example below, two types of groups are created: one by administrative region of the World Bank, and one by income level. Within a type, the groups do not have to be mutually exclusive. A country can belong to multiple groups.</p><h2 id="using-the-administrator-interface" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>A region or type of region is created by clicking on the &quot;Create region&quot; button, then entering the relevant information. If you create a region without specifying a &quot;parent&quot;, you are creating a region parent. If you create a region and specify a &quot;parent&quot;, you are creating a group within this parent group.</p><p><img src="'+s+'" alt=""></p><p>Once a region has been created, the countries that belong to it can be selected (from the reference list of countries). The &quot;weight&quot; argument is a numeric value that will determine the order in which regions are to be displayed. Lower weight higher or lower?</p><p><img src="'+c+'" alt=""></p><p>Groups can be edited or deleted; this does not impact the metadata in the catalog in any way.</p><h2 id="using-the-api" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>Uploading and maintaining a list of countries</p><p>R</p><p>Python</p>',14)])])}const b=t(g,[["render",d]]);export{_ as __pageData,b as default};
